      "content": "{\n  \"name\": \"dsh-inject\",\n  \"version\": \"0.3.3\",\n  \"description\": \"Advanced model-context injection and request-only rewriting for DeepSeek Harness with Keysmith rules compatibility. dsh-inject：为 DeepSeek Harness 提供高级上下文注入与请求侧消息重写，兼容 Keysmith 规则集。\",\n  \"license\": \"MIT\",\n  \"author\": \"johnnren\",\n  \"type\": \"module\",\n  \"main\": \"./lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.en.md\",\n    \"LICENSE\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/john-walks-slow/dsh-inject.git\"\n  },\n  \"homepage\": \"https://github.com/john-walks-slow/dsh-inject#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/john-walks-slow/dsh-inject/issues\"\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"cordis-plugin\",\n    \"context-injection\",\n    \"rewrite\",\n    \"keysmith\",\n    \"prompt-injection\",\n    \"上下文管理\",\n    \"请求重写\",\n    \"预设\",\n    \"jailbreak\",\n    \"破甲\",\n    \"越狱\",\n    \"prompt-rewriting\"\n  ],\n  \"scripts\": {\n    \"build\": \"node scripts/build.mjs\",\n    \"build:client\": \"node scripts/build-client.mjs\",\n    \"check\": \"node --input-type=module -e \\\"await import('./lib/index.js')\\\" && node --check lib/client.js\",\n    \"test\": \"node --test test/*.test.mjs\",\n    \"e2e:commands\": \"dsh-e2e run e2e/verify-commands.mjs\",\n    \"e2e:dialog\": \"dsh-e2e run e2e/verify-dialog.mjs\",\n    \"e2e:row\": \"dsh-e2e run e2e/verify-inject-row.mjs\",\n    \"e2e:defaults\": \"dsh-e2e run e2e/verify-default-enabled.mjs\",\n    \"e2e:save\": \"dsh-e2e run e2e/verify-manual-save.mjs\",\n    \"e2e:injection\": \"dsh-e2e run e2e/verify-injection-e2e.mjs\",\n    \"e2e:shots\": \"dsh-e2e run e2e/screenshot-inject.mjs\",\n    \"prepare\": \"npm run build\",\n    \"prepublishOnly\": \"npm test\",\n    \"release\": \"npm run test && npm version patch && npm pack --pack-destination /tmp\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-ui-settings\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-llm\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/schemastery\": \"3.18.5\",\n    \"@types/react\": \"~18.3.1\",\n    \"esbuild\": \"^0.28.2\",\n    \"react\": \"^18.3.1\"\n  },\n  \"engines\": {\n    \"node\": \">=22.5\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh-llm\": \"^0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"^0.2.1-rc.2\",\n    \"@deepseek-ai/schemastery\": \"~3.18.5\"\n  }\n}\n"
